/**
 * @name SQL injection in pandas SQL operations
 * @description User input flowing into SQL queries without proper sanitization
 * @kind path-problem
 * @problem.severity error
 * @id py/sql-injection-pandas
 * @tags security
 *        external/cwe/cwe-089
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.dataflow.new.RemoteFlowSources
import semmle.python.Concepts
import semmle.python.ApiGraphs

module PandasSqlConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    source instanceof RemoteFlowSource
  }

  predicate isSink(DataFlow::Node sink) {
    // Check for SQL execution calls in pandas
    sink = API::moduleImport("pandas").getMember(["read_sql", "read_sql_query", "read_sql_table"]).getACall() or
    sink = API::moduleImport("pandas.io.sql").getMember(["read_sql", "read_sql_query", "read_sql_table"]).getACall()
  }
}

module PandasSqlFlow = TaintTracking::Global<PandasSqlConfig>;
import PandasSqlFlow::PathGraph

from PandasSqlFlow::PathNode source, PandasSqlFlow::PathNode sink
where PandasSqlFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "SQL injection in pandas SQL operation from $@.", source.getNode(), "user input"

/**
 * @name SQL injection in pandas SQL operations
 * @description SQL injection vulnerability when untrusted data flows to SQL query execution
 * @kind path-problem
 * @problem.severity error
 * @id py/pandas-sql-injection
 * @tags security
 *        external/cwe/cwe-089
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.dataflow.new.RemoteFlowSources
import semmle.python.Concepts
import semmle.python.ApiGraphs

module PandasSqlConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    source instanceof RemoteFlowSource
  }

  predicate isSink(DataFlow::Node sink) {
    // Look for SQL execution methods in pandas - first argument is SQL query
    exists(API::CallNode call | 
      call = API::moduleImport("pandas").getMember(["read_sql", "read_sql_query", "read_sql_table"]).getACall() 
      and sink = call.getArg(0)
    )
    or
    // SQLAlchemy text() function - first argument is SQL query
    exists(API::CallNode call | 
      call = API::moduleImport("sqlalchemy").getMember("text").getACall()
      and sink = call.getArg(0)
    )
    or
    // SQLAlchemy execute methods - first argument is SQL query
    exists(API::CallNode call | 
      call = API::moduleImport("sqlalchemy").getMember(["execute", "exec_driver_sql"]).getACall()
      and sink = call.getArg(0)
    )
  }
}

module PandasSqlFlow = TaintTracking::Global<PandasSqlConfig>;
import PandasSqlFlow::PathGraph

from PandasSqlFlow::PathNode source, PandasSqlFlow::PathNode sink
where PandasSqlFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "SQL injection vulnerability from $@.", source.getNode(), "user input"
